css:
[data-bz-node="ps"] { max-width: 1180px; margin: 0; padding: 80px 40px 40px clamp(40px, 7vw, 120px); text-align: left; }
[data-bz-node="ps-label"].bz-block p { margin: 0; padding-top: 5px; font-family: var(--font-heading); font-weight: 400; font-size: 12px; line-height: 14px; letter-spacing: .3em; text-transform: uppercase; color: #6f8498; max-width: none; }
[data-bz-node="ps-grid"] { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 16px; margin-top: 26px; }
[data-bz-node="ps-grid"] > .bz-col { grid-column: auto; height: 84px; display: flex; align-items: center; justify-content: center; }
[data-bz-node="ps-grid"] > .bz-col > .bz-block { width: 100%; height: 100%; }
[data-bz-node="ps-grid"] .bz-container, [data-bz-node="ps-grid"] .bz-figure { height: 100%; margin: 0; }
[data-bz-node="ps-grid"] img { max-height: 84px; width: auto; max-width: 100%; margin: 0 auto; border-radius: 0; }
[data-bz-node="ps-grid"] .bz-photo--empty { width: 100%; height: 84px; border-radius: 10px; border: 0; font-size: 0; background: repeating-linear-gradient(135deg, rgba(255,255,255,.045) 0 10px, rgba(255,255,255,.015) 10px 20px); outline: 1px dashed rgba(255,255,255,.18); outline-offset: -1px; }
